90	// runRegister processes registration requests from standard input.
91	// It returns the process exit code: 0 when all registrations succeed, 1 otherwise.
92	func runRegister() int {
93		data, err := io.ReadAll(os.Stdin)
94		if err != nil {
95			return failRegister(fmt.Sprintf("could not read standard input: %v", err))
96		}
97	
98		var top struct {
99			Requests json.RawMessage `json:"requests"`
100		}
101		if err := json.Unmarshal(data, &top); err != nil {
102			return failRegister(fmt.Sprintf("input must be a JSON object with a requests array: %v", err))
103		}
104		if len(top.Requests) == 0 || strings.TrimSpace(string(top.Requests)) == "null" {
105			return failRegister("input must contain a \"requests\" array")
106		}
107		var rawRequests []json.RawMessage
108		if err := json.Unmarshal(top.Requests, &rawRequests); err != nil {
109			return failRegister("\"requests\" must be a JSON array")
110		}
111	
112		proc := &registerProcessor{
113			registry: indexroom.NewRegistry(),
114			results:  make([]registerResult, 0, len(rawRequests)),
115		}
116	
117		for _, raw := range rawRequests {
118			var head struct {
119				Service string          `json:"service"`
120				Type    json.RawMessage `json:"type"`
121			}
122			_ = json.Unmarshal(raw, &head)
123			service := strings.TrimSpace(head.Service)
124	
125			reqType := "register"
126			if len(head.Type) > 0 && strings.TrimSpace(string(head.Type)) != "null" {
127				var t string
128				if err := json.Unmarshal(head.Type, &t); err != nil {
129					proc.invalid(service, "type must be a string")
130					continue
131				}
132				reqType = t
133			}
134	
135			switch reqType {
136			case "", "register":
137				proc.registerRequest(raw, service)
138			case "health":
139				proc.healthRequest(raw, service)
140			case "select":
141				proc.selectRequest(raw, service)
142			default:
143				proc.invalidf(service, "unknown type %q", reqType)
144			}
145		}
146	
147		results, anyFailed := proc.results, proc.failed
148		registry := proc.registry
149	
150		services := make([]registerService, 0)
151		for _, view := range registry.Snapshot() {
152			insts := make([]registerInstance, 0, len(view.Instances))
153			for _, inst := range view.Instances {
154				insts = append(insts, registerInstance{
155					ID:       inst.ID,
156					Address:  inst.Address,
157					Health:   string(inst.Health),
158					Sequence: inst.Sequence,
159					Reason:   inst.Reason,
160				})
161			}
162			services = append(services, registerService{
163				Service:   view.Service,
164				Revision:  view.Revision,
165				Instances: insts,
166			})
167		}
168	
169		writeRegisterOutput(registerOutput{Results: results, Services: services})
170		if anyFailed {
171			return 1
172		}
173		return 0
174	}
