678	func TestSelectAddressReplacementNoHealthyThenRecovery(t *testing.T) {
679		// Replacing the only healthy instance's address leaves no healthy target:
680		// select reports no_healthy without moving the cursor, a health report
681		// against the old revision conflicts without healing the new address, and
682		// a fresh observation at the current revision (sequence only above the
683		// reset 0, not above the old accepted one) makes the new address eligible
684		// again.
685		input := `{"requests":[
686			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"}]},
687			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":20,"healthy":true},
688			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":21,"healthy":false,"reason":"down"},
689			{"type":"select","service":"svc","expectedRevision":1},
690			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"}]},
691			{"type":"select","service":"svc","expectedRevision":2},
692			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":99,"healthy":true},
693			{"type":"select","service":"svc","expectedRevision":2},
694			{"type":"health","service":"svc","instanceId":"a","expectedRevision":2,"sequence":1,"healthy":true},
695			{"type":"health","service":"svc","instanceId":"b","expectedRevision":2,"sequence":22,"healthy":true},
696			{"type":"select","service":"svc","expectedRevision":2},
697			{"type":"select","service":"svc","expectedRevision":2}
698		]}`
699		out, code := runRegisterWith(t, input)
700		if code != 1 {
701			t.Fatalf("exit code: %d, output: %s", code, out)
702		}
703		var got registerOutput
704		if err := json.Unmarshal([]byte(out), &got); err != nil {
705			t.Fatalf("output is not JSON: %v\n%s", err, out)
706		}
707		if len(got.Results) != 12 {
708			t.Fatalf("results: %+v", got.Results)
709		}
710		// Cursor rests on a before the replacement.
711		if r := got.Results[3]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 20 {
712			t.Fatalf("select before replacement: %+v", r)
713		}
714		if r := got.Results[4]; !r.OK || !r.Changed || r.Revision != 2 {
715			t.Fatalf("address replacement: %+v", r)
716		}
717		// No healthy instance remains: no_healthy states the reason and the current
718		// revision and fabricates neither an instance id nor an address.
719		if r := got.Results[5]; r.OK || r.Error != "no_healthy" || r.Reason == "" || r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
720			t.Fatalf("no_healthy after replacement: %+v", r)
721		}
722		// A health report against the old revision conflicts even though its
723		// sequence (99) exceeds the old accepted one (20); it names both revisions.
724		if r := got.Results[6]; r.OK || r.Error != "conflict" || r.Reason == "" || r.ExpectedRevision != 1 || r.ActualRevision != 2 || r.Revision != 2 {
725			t.Fatalf("stale-revision health report: %+v", r)
726		}
727		// The conflicting report did not heal the new address: still no_healthy.
728		if r := got.Results[7]; r.OK || r.Error != "no_healthy" || r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
729			t.Fatalf("new address must not regain eligibility from old revision: %+v", r)
730		}
731		// At the current revision a sequence just above the reset 0 suffices; it
732		// does not need to exceed the 20 accepted for the old address.
733		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 1 {
734			t.Fatalf("fresh observation at current revision: %+v", r)
735		}
736		if r := got.Results[9]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 22 {
737			t.Fatalf("b recovery: %+v", r)
738		}
739		// The failed selects and health report never moved the cursor off a, so
740		// the rotation continues at b rather than restarting at the smallest id.
741		if r := got.Results[10]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 22 || r.Revision != 2 {
742			t.Fatalf("rotation should resume after a at b: %+v", r)
743		}
744		// The new address rejoins selection carrying its new address and the new
745		// observation's sequence.
746		if r := got.Results[11]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 2 {
747			t.Fatalf("new address should be selected with its new observation: %+v", r)
748		}
749		// The final list reflects only the committed changes.
750		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
751			t.Fatalf("services: %+v", got.Services)
752		}
753		insts := got.Services[0].Instances
754		if len(insts) != 2 {
755			t.Fatalf("instances: %+v", insts)
756		}
757		if insts[0].ID != "a" || insts[0].Address != "h9:9" || insts[0].Health != "healthy" || insts[0].Sequence != 1 || insts[0].Reason != "" {
758			t.Fatalf("a should be healthy at its new address: %+v", insts[0])
759		}
760		if insts[1].ID != "b" || insts[1].Address != "h2:2" || insts[1].Health != "healthy" || insts[1].Sequence != 22 || insts[1].Reason != "" {
761			t.Fatalf("b should be healthy again: %+v", insts[1])
762		}
