797		// Stale: sequence below the accepted 7. The failure states the reason and
798		// the currently accepted sequence, and keeps the service revision.
799		if r := got.Results[4]; r.OK || r.Error != "stale" ||
800			r.Reason != "sequence 3 is older than the current sequence 7" ||
801			r.Sequence != 7 || r.Revision != 1 {
802			t.Fatalf("stale report: %+v", r)
803		}
804		// Conflict: the accepted sequence 7 reused with the opposite health state.
805		if r := got.Results[5]; r.OK || r.Error != "conflict" ||
806			r.Reason != "sequence 7 already used with different health content" ||
807			r.Sequence != 7 || r.Revision != 1 {
808			t.Fatalf("conflicting report: %+v", r)
809		}
810		// The rejected "unhealthy" reports did not knock b out: the rotation
811		// continues just after a and lands on b with its accepted record.
812		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 7 || r.Revision != 1 {
813			t.Fatalf("select after rejections should still choose b: %+v", r)
814		}
815		// Past the end the rotation wraps to the smallest id.
816		if r := got.Results[7]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 5 {
817			t.Fatalf("select should wrap to a: %+v", r)
818		}
819		// The final list shows only the accepted observations; nothing from the
820		// rejected reports leaked in.
821		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
822			t.Fatalf("services: %+v", got.Services)
823		}
824		insts := got.Services[0].Instances
825		if len(insts) != 2 {
826			t.Fatalf("instances: %+v", insts)
827		}
828		if insts[0].ID != "a" || insts[0].Health != "healthy" || insts[0].Sequence != 5 || insts[0].Reason != "" {
829			t.Fatalf("a should keep its accepted record: %+v", insts[0])
830		}
831		if insts[1].ID != "b" || insts[1].Health != "healthy" || insts[1].Sequence != 7 || insts[1].Reason != "" {
832			t.Fatalf("b should keep its accepted record: %+v", insts[1])
833		}
834	}
