836	func TestRejectedHealthDoesNotRestoreUnhealthyInstance(t *testing.T) {
837		// The opposite direction: an unhealthy instance that receives a stale or
838		// same-sequence conflicting "healthy" report stays unhealthy and never
839		// re-enters the candidate set; the rotation keeps repeating the only
840		// healthy instance.
841		input := `{"requests":[
842			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"}]},
843			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":4,"healthy":true},
844			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":6,"healthy":false,"reason":"connection refused"},
845			{"type":"select","service":"svc","expectedRevision":1},
846			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":2,"healthy":true},
847			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":6,"healthy":true},
848			{"type":"select","service":"svc","expectedRevision":1}
849		]}`
850		out, code := runRegisterWith(t, input)
851		if code != 1 {
852			t.Fatalf("exit code: %d, output: %s", code, out)
853		}
854		var got registerOutput
855		if err := json.Unmarshal([]byte(out), &got); err != nil {
856			t.Fatalf("output is not JSON: %v\n%s", err, out)
857		}
858		if len(got.Results) != 7 {
859			t.Fatalf("results: %+v", got.Results)
860		}
861		if r := got.Results[3]; !r.OK || r.InstanceID != "a" || r.Sequence != 4 {
862			t.Fatalf("first select: %+v", r)
863		}
864		// Stale "healthy" report: rejected, the accepted sequence 6 is reported.
865		if r := got.Results[4]; r.OK || r.Error != "stale" ||
866			r.Reason != "sequence 2 is older than the current sequence 6" ||
867			r.Sequence != 6 || r.Revision != 1 {
868			t.Fatalf("stale recovery attempt: %+v", r)
869		}
870		// Same sequence 6 flipping unhealthy to healthy: conflict.
871		if r := got.Results[5]; r.OK || r.Error != "conflict" ||
872			r.Reason != "sequence 6 already used with different health content" ||
873			r.Sequence != 6 || r.Revision != 1 {
874			t.Fatalf("conflicting recovery attempt: %+v", r)
875		}
876		// b was not restored: a is still the only healthy instance and is chosen
877		// again with its accepted record.
878		if r := got.Results[6]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 4 || r.Revision != 1 {
879			t.Fatalf("select should repeat the only healthy instance: %+v", r)
880		}
881		// The final list keeps the accepted unhealthy record with its reason.
882		insts := got.Services[0].Instances
883		if len(insts) != 2 {
884			t.Fatalf("instances: %+v", insts)
885		}
886		if insts[0].ID != "a" || insts[0].Health != "healthy" || insts[0].Sequence != 4 || insts[0].Reason != "" {
887			t.Fatalf("a should keep its accepted record: %+v", insts[0])
888		}
889		if insts[1].ID != "b" || insts[1].Health != "unhealthy" || insts[1].Sequence != 6 || insts[1].Reason != "connection refused" {
890			t.Fatalf("b should keep its accepted unhealthy record: %+v", insts[1])
891		}
892	}
