894	func TestRejectedRecoveryKeepsNoHealthyUntilNewerSequence(t *testing.T) {
895		// With no healthy instance, rejected recovery attempts change nothing:
896		// select keeps returning no_healthy without a target instance or address.
897		// Only a later report with a higher sequence is accepted, and the next
898		// selection uses that new record rather than the rejected content.
899		input := `{"requests":[
900			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"}]},
901			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":9,"healthy":false,"reason":"down"},
902			{"type":"select","service":"svc","expectedRevision":1},
903			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":4,"healthy":true},
904			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":9,"healthy":true},
905			{"type":"select","service":"svc","expectedRevision":1},
906			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":10,"healthy":true},
907			{"type":"select","service":"svc","expectedRevision":1}
908		]}`
909		out, code := runRegisterWith(t, input)
910		if code != 1 {
911			t.Fatalf("exit code: %d, output: %s", code, out)
912		}
913		var got registerOutput
914		if err := json.Unmarshal([]byte(out), &got); err != nil {
915			t.Fatalf("output is not JSON: %v\n%s", err, out)
916		}
917		if len(got.Results) != 8 {
918			t.Fatalf("results: %+v", got.Results)
919		}
920		// No healthy instance: no_healthy names neither an instance nor an address.
921		if r := got.Results[2]; r.OK || r.Error != "no_healthy" || r.Reason == "" || r.Revision != 1 || r.InstanceID != "" || r.Address != "" {
922			t.Fatalf("select with no healthy instance: %+v", r)
923		}
924		// Stale recovery attempt reports the accepted sequence 9.
925		if r := got.Results[3]; r.OK || r.Error != "stale" ||
926			r.Reason != "sequence 4 is older than the current sequence 9" ||
927			r.Sequence != 9 || r.Revision != 1 {
928			t.Fatalf("stale recovery attempt: %+v", r)
929		}
930		// Same sequence 9 flipping to healthy conflicts.
931		if r := got.Results[4]; r.OK || r.Error != "conflict" ||
932			r.Reason != "sequence 9 already used with different health content" ||
933			r.Sequence != 9 || r.Revision != 1 {
934			t.Fatalf("conflicting recovery attempt: %+v", r)
935		}
936		// The rejected recoveries did not restore eligibility: still no_healthy.
937		if r := got.Results[5]; r.OK || r.Error != "no_healthy" || r.Revision != 1 || r.InstanceID != "" || r.Address != "" {
938			t.Fatalf("rejected recoveries must not restore eligibility: %+v", r)
939		}
940		// A higher sequence is accepted and flips the instance to healthy.
941		if r := got.Results[6]; !r.OK || !r.Changed || r.Sequence != 10 || r.Revision != 1 {
942			t.Fatalf("newer recovery: %+v", r)
943		}
944		// The next selection uses the newly accepted record (sequence 10), not
945		// anything from the rejected reports.
946		if r := got.Results[7]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 10 || r.Revision != 1 {
947			t.Fatalf("select after accepted recovery: %+v", r)
948		}
949		// Final list: healthy at sequence 10 with the old reason cleared.
950		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
951			t.Fatalf("services: %+v", got.Services)
952		}
953		insts := got.Services[0].Instances
954		if len(insts) != 1 || insts[0].ID != "a" || insts[0].Health != "healthy" || insts[0].Sequence != 10 || insts[0].Reason != "" {
955			t.Fatalf("a should be healthy at sequence 10: %+v", insts)
956		}
957	}
