959	func TestSelectDeterministic(t *testing.T) {
960		input := `{"requests":[
961			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"c","address":"h3:3"},{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"}]},
962			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":3,"healthy":true},
963			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":1,"healthy":true},
964			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":2,"healthy":true},
965			{"type":"select","service":"svc","expectedRevision":1},
966			{"type":"select","service":"svc","expectedRevision":1}
967		]}`
968		out1, _ := runRegisterWith(t, input)
969		out2, _ := runRegisterWith(t, input)
970		if out1 != out2 {
971			t.Fatalf("non-deterministic output:\n%s\nvs\n%s", out1, out2)
972		}
973	}
